def caesar_shift(s, shift):
    shift = shift % 26
    res = ''
    for c in s:
        o = ord(c)
        if 'a' <= c <= 'z':
            res += chr((o - ord('a') + shift) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            res += chr((o - ord('A') + shift) % 26 + ord('A'))
        else:
            res += c
    return res
