def reorder_by_priority_groups(items, category_of, priority):
    categorized = {}
    for cat in priority:
        categorized[cat] = []
    uncategorized = []
    for item in items:
        cat = category_of[item]
        if cat in categorized:
            categorized[cat].append(item)
        else:
            uncategorized.append(item)
    return [categorized[p] for p in priority if p in categorized] + uncategorized
```

